page(s,[('Отправка и ответ',['При чтении личного сообщения сохраняйте действие. Намерение отправить сообщение не заменяет намерение ответить на него.'],[ex('Je vais envoyer le message demain.','Я собираюсь отправить сообщение завтра.','жё вэ а(н)вуайе лё мэсаж дёмэ́(н)'),ex('Je vais répondre au message ce soir.','Я собираюсь ответить на сообщение сегодня вечером.','жё вэ рэпо(н)др о мэсаж сё суа́р')]),('Время и отрицание',['Отрицательный план не считается положительным. Время встречи и время ответа читаются в своих частях сообщения.'],[ex('Je ne vais pas envoyer le message ce soir.','Я не собираюсь отправлять сообщение сегодня вечером.','жё нё вэ па а(н)вуайе лё мэсаж сё суа́р')]),('Адресат и автор',['В показанном учебном шаблоне имя после приветствия — адресат, имя после завершения — подпись автора. Имена вымышленные.'],[ex('Bonjour Marie. À bientôt. Luc.','Здравствуйте, Мари. До скорого. Люк.','бо(н)жур мари́. а бьэ(н)то́. лю́к')])])
