coverage=[dict(objective_id=o,evidence=[dict(session_id=s['id'],task_id=t['id'],skill=t['skill']) for s in S for t in s['tasks'] if o in t['objective_ids']]) for o in dict.fromkeys(o['id'] for s in S for o in s['objectives'])]
D=dict(unit_id=plan['id'],package_file=target.name,session_ids=[s['id'] for s in S],new_lexemes=[dict(**{k:W[w][k] for k in ['id','lexeme_key','fr','ru','transcription_ru']},first_session_id=S[n-1]['id']) for w,n in FIRST.items()],reused_lexeme_keys=sorted({w['lexeme_key'] for s in S for w in s['vocabulary'] if w['id'] in OLD}),objective_coverage=coverage,
 review_targets_for_next_unit=[dict(lexeme_key=W[w]['lexeme_key'],reason=r) for w,r in [('prendre-transport','Вернуть транспортное значение при подготовке поездки A2.'),('billet','Повторить билет как отдельный предмет поездки.'),('gare','Вернуть вокзал как транспортный ориентир.'),('reservation','Повторить бронирование, сохранив контекст гостиницы.'),('demain','Сохранить день будущего действия.'),('envoyer','Повторить отправку короткого сообщения отдельно от ответа.'),('retrouver','Повторить назначенную встречу с человеком.'),('aller-futur','Сохранить рамку ближайшего намерения.'),('je-voudrais','Вернуть знакомую вежливую просьбу.')]],
 checks=dict(json_parsed=False,schema_validated=False,site_preview_passed=False,browser_audio_checked=False,language_reviewed_by_human=False),
 open_issues=['До импорта целевая база должна содержать A1-U19-L05; пакет не создаёт внешнюю зависимость.','Редактору проверить естественность французских бытовых реплик и двух новых контекстных значений, транскрипции и сложность итогового контроля.','Прослушать браузерную озвучку часов, числительных, транспортных сочетаний и имён. Время аудио и занятий не измерено.','Выполнить предпросмотр и пробное прохождение пяти занятий, включая контроль. Контроль не является подтверждением всего CEFR A1.'],
 progress=dict(current_unit=plan['id'],prepared_session_ids=[s['id'] for s in S],user_accepted_session_ids=[],remaining_session_ids=[],next_unit_not_started='A2-U01',next_unit_title='Подготовка поездки',previous_unit='A1-U19',previous_unit_advance_authorized=True,previous_unit_import_confirmed=False),
 scope_notes=['Команда «Следующий этап» разрешает подготовку A1-U20. Принятие и импорт предыдущих пакетов не подтверждены; повторение использует полные объекты подготовленных пакетов.','Интегративная тема вводит только два новых значения: одно в L01 и одно в L03. Остальные слова и конструкции повторяются. L05 не вводит нового обязательного материала.','Prendre в транспортном сочетании получает fr:prendre:use-transport. Прежние значения завтрака и выбора товара не переписываются и не объединяются с транспортным.','Retrouver показано как встреча с человеком по договорённости, не поиск вещи. Новое значение используется в знакомой рамке Je vais, без новой полной таблицы спряжения.','Envoyer, répondre, завтрак, рабочие действия, занятие, покупка, количество, время, приветствие и подпись сохраняют прежние ключи.','В L01 повторена последовательность действий A1-U19, в L03 — явное обещание A1-U17, в L04 — планы выходных A1-U17. Повторение подготовленного материала не подтверждает его принятие или освоение.','Дни и часы относятся к отдельному действию: час завтрака не переносится на поездку, время работы — на занятие, время встречи — на ответ.','В образце личного сообщения имя после приветствия обозначает адресата, имя после завершения — автора. Имена вымышленные, реальные сообщения никому не отправляются.','L05 имеет kind=checkpoint и восемь вопросов: два listening, два reading, два vocabulary, один grammar, один sentence_building. Вводная карточка описывает процедуру без готовых ответов.','Контроль возвращает кафе U03, одежду U05, гостиницу U08, работу U11, учёбу U12, погоду U15, план U17, сообщение U18 и запрет U19. Теги назначены конкретным проверяемым действиям, а не всем целям уровня сразу.','Восемь вопросов — выборка бытовых ситуаций. Формальное покрытие сорока обязательных целей проверяется накопительно по всем ста занятиям; оно не доказывает смысловое качество без редактора и не подтверждает свободную речь.','После завершения темы проверяется подготовленный комплект A1. Публикация, принятие пользователем и достижения ученика не выводятся из наличия файлов.','Пакет содержит только текущую тему без levels и curricula. Сборка программы перехода между уровнями — отдельная задача, здесь не выполняется. Основной реестр, прежние пакеты и база сайта не изменялись.'])
